abstract class Shape {
    private final String color;              // instance field — shared state

    Shape(String color) {                    // constructor — called via super()
        this.color = color;
    }

    public String getColor() {               // concrete method — inherited as-is
        return color;
    }

    public abstract double area();           // abstract method — subclass must implement

    public void describe() {                 // template method — uses the abstract hook
        System.out.printf("%s shape, area = %.2f%n", color, area());
    }
}

class Circle extends Shape {
    private final double radius;

    Circle(String color, double radius) {
        super(color);                        // calls Shape's constructor
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;    // Circle's implementation
    }
}

class Rectangle extends Shape {
    private final double width, height;

    Rectangle(String color, double w, double h) {
        super(color);
        this.width = w;
        this.height = h;
    }

    @Override
    public double area() {
        return width * height;               // Rectangle's implementation
    }
}

public class AbstractClassDemo {
    public static void main(String[] args) {
        // Shape s = new Shape("red");       // COMPILE ERROR — cannot instantiate abstract class

        Shape c = new Circle("red", 5);
        Shape r = new Rectangle("blue", 4, 6);

        c.describe();  // red shape, area = 78.54
        r.describe();  // blue shape, area = 24.00
    }
}
