abstract class Shape {
    // ── Legal abstract methods ─────────────────────────────────────
    public abstract double area();           // legal: public + abstract
    protected abstract String describe();    // legal: protected + abstract
    abstract void draw();                    // legal: package-private + abstract

    // ── Illegal abstract methods ───────────────────────────────────
    // private abstract void log();          // ILLEGAL: private — subclass can't see it
    // static abstract void create();        // ILLEGAL: static — not overridable
    // final abstract void lock();           // ILLEGAL: final — explicitly forbids override

    // ── Body on abstract method is illegal ─────────────────────────
    // abstract double area() { return 0; }  // ILLEGAL: abstract method must have no body
}

// ── Concrete subclass MUST implement every abstract method ──────────
class Circle extends Shape {
    private final double radius;

    Circle(double radius) { this.radius = radius; }

    @Override
    public double area() { return Math.PI * radius * radius; }   // must implement

    @Override
    protected String describe() { return "Circle r=" + radius; } // must implement

    @Override
    void draw() { System.out.println("Drawing circle"); }        // must implement
}

// ── Partial subclass must itself be abstract ───────────────────────
abstract class PartialShape extends Shape {
    @Override
    public double area() { return 0; }       // implements area() only
    // describe() and draw() still abstract → class must be abstract
}
